const body = $json.body || {};
const query = String(body.query || '').trim();
if (query.length < 2 || query.length > 200) throw new Error('query must contain 2-200 characters');
const maxResults = Math.min(Math.max(Number(body.max_results || 10), 1), 25);
const creativeCommonsOnly = body.creative_commons_only !== false;
const params = {
  part: 'snippet', type: 'video', q: query, maxResults, order: 'relevance',
  safeSearch: 'moderate', videoEmbeddable: 'true', key: $env.YOUTUBE_API_KEY
};
if (creativeCommonsOnly) params.videoLicense = 'creativeCommon';
if (body.published_after) params.publishedAfter = String(body.published_after);
if (body.region_code) params.regionCode = String(body.region_code);
return [{json: {query, creativeCommonsOnly, params}}];

const owned = new Set(String($env.YOUTUBE_OWNED_CHANNEL_IDS || '').split(',').map(x => x.trim()).filter(Boolean));
const candidates = ($json.items || []).map(v => {
  const s = v.snippet || {}, st = v.status || {}, c = v.contentDetails || {}, stats = v.statistics || {};
  const isOwned = owned.has(s.channelId);
  const isCC = st.license === 'creativeCommon';
  const reusable = isOwned || isCC;
  const views = Number(stats.viewCount || 0), likes = Number(stats.likeCount || 0);
  const score = (reusable ? 45 : 0) + (st.embeddable ? 10 : 0) + (c.definition === 'hd' ? 5 : 0) + Math.min(20, views / 50000) + Math.min(10, likes / 5000);
  const thumb = s.thumbnails?.high?.url || s.thumbnails?.medium?.url || s.thumbnails?.default?.url || '';
  return {video_id:v.id,title:s.title||'',channel_id:s.channelId||'',channel_title:s.channelTitle||'',published_at:s.publishedAt||'',duration:c.duration||'',definition:c.definition||'',license:st.license||'youtube',embeddable:!!st.embeddable,view_count:views,like_count:likes,thumbnail_url:thumb,watch_url:`https://www.youtube.com/watch?v=${v.id}`,risk_level:reusable?'green':'red',reusable,score:Number(score.toFixed(2)),reason:isOwned?'Owned channel':isCC?'Creative Commons; verify attribution and uploader authority':'Standard license; discovery only'};
}).sort((a,b)=>b.score-a.score);
return [{json:{generated_at:new Date().toISOString(),candidate_count:candidates.length,reusable_count:candidates.filter(x=>x.reusable).length,candidates,download_performed:false}}];
